INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (1, 1, 'data-fusion', '多维数据融合应用平台', '一零智搜、档案中心、一人一档、一车一档、布控中心、卡口围栏', '融合政务、公安、物联网和社会资源多维数据，一键智能查询人员全量数据，形成“区域一张网”。', '/images/jiejueone.jpg', '["/images/jiejueone.jpg", "/images/duoweironghe.png"]', '<p>为实现“让数据多跑路、让民警少跑路”的目标，针对县区内政务、公安、物联网和社会资源等应用系统积累海量数据，但各系统数据相对独立，未能产生关联，数据利用率不高的现状，北京一零科技有限公司将多维度的数据进行融合，打通各系统之间通道，结合人、地、事、物、组织、时空等管理要素，一键智能查询相关人员全量数据，并将业务数据的时空属性结合GIS系统形成“区域一张网”，进行全面可视化展示，为情报研判、指挥调度、领导决策等实战应用提供支撑。</p><h3>整合数据</h3><ul><li>公安</li><li>政务</li><li>物联网</li><li>社会资源数据</li><li>智能终端</li></ul><h3>卡口围栏</h3><ul><li>伴随分析</li><li>人像布控</li><li>车辆布控</li></ul><h3>数据应用</h3><ul><li>一人一档</li><li>一车一档</li><li>智能搜索</li></ul><h3>可视化</h3><ul><li>电动车轨迹</li><li>机动车轨迹</li><li>可视化指挥</li></ul><h3>方案图解</h3><p><img src="/images/duoweironghe.png" alt="多维数据融合应用平台方案图解"></p>', 'REMOTE_DEPLOY', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '含 1 年免费运维与版本升级', 1, 1, 1);
