INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (2, 1, 'police-station', '新时代公安派出所多维数据融合平台', '全面推进新时代公安派出所“两队一室”标准化建设', '面向派出所“两队一室”改革，提供人像车辆无感采集、布控与多渠道实时预警，实现警力资源部署一张图。', '/images/jiejuefour.jpg', '["/images/jiejuefour.jpg", "/images/newgongan.png"]', '<p>当前公安派出所面临着数据种类繁多，如何将数据应用到实战等诸多难题；同时在警务繁多、警力资源紧张的情况下如何合理调配警力资源问题亟待解决；事前精准预测、事中快速反应和事后全程跟踪等工作急需科技手段支撑。</p><p>2023年3月，公安部印发《加强新时代公安派出所工作三年行动计划（2023-2025年）》，文件提出要加强全面深化“两队一室”改革，进一步增强派出所实力、激发活力、提升战斗力。同时，践行“警网融合”理念：通过整合公安力量和社会资源，提高社会治理的效率和效果。为响应文件思想并结合当前公安派出所面临困境，建设新时代公安派出所多维数据融合平台。</p><h3>感知终端</h3><ul><li>AI智能执法记录仪</li><li>警用智能终端</li></ul><h3>建设内容</h3><ul><li>人像车辆实时无感采集</li><li>人像车辆布控</li><li>预警信息可视化</li><li>多渠道实时预警</li></ul><h3>建设目标</h3><ul><li>警力资源部署一张图</li><li>警力资源优化</li><li>重点人员车辆管理</li><li>可视化指挥</li></ul><h3>方案图解</h3><p><img src="/images/newgongan.png" alt="新时代公安派出所多维数据融合平台方案图解"></p>', 'REMOTE_DEPLOY', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '含 1 年免费运维与版本升级', 1, 1, 2);
