INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (3, 1, 'security-assistant', '治安小助手', '两队一室建设、民警应用的基础软件', '对接公安部移动安全边界的移动警务APP，民警通过警务通录入数据，实现与公安网安全交互。', '/images/jiejuethree.png', '["/images/jiejuethree.png", "/images/xiaohand.png"]', '<p>对接公安部移动安全边界，民警通过警务通“应用中心”下载移动警务APP，通过移动警务APP将数据录入公安网，实现与公安网数据交互，同时保证数据安全。移动警务APP的使用，使警务工作由“传统粗放型”向“集约高效型”转变，避免“人海战术”，进一步解放警力；同时推动县区信息化建设，为公安、智慧城市等平台建设提供坚实的数据支撑。</p><h3>数据安全</h3><ul><li>对接移动安全边界，民警通过警务通手机实现与公安网络数据交互</li></ul><h3>解放警力资源</h3><ul><li>避免人海战术、提高工作效率、解放警力资源</li></ul><h3>监管考核</h3><ul><li>结合时空信息实现民警日常工作监管、考核，通过动态积分方式实现“以考导防”</li></ul><h3>推动信息化建设</h3><ul><li>建设县域特有数据资源池，推动县域信息化建设</li></ul><h3>方案图解</h3><p><img src="/images/xiaohand.png" alt="治安小助手方案图解"></p>', 'DOWNLOAD_LICENSE', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '含 1 年免费运维与版本升级', 1, 1, 3);
