INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (4, 2, 'business-env', '营商环境门户平台', '建设三级联网全覆盖的一体化网上服务体系', '标准化办事要件和办事指南，整合数据资源，实现“一网通办”，助力政府优化营商环境。', '/images/jiejuetwo.jpg', '["/images/jiejuetwo.jpg", "/images/huanjing.png"]', '<p>基于国务院《优化营商环境条例》《河南省优化营商环境条例》和《国务院办公厅关于规范营商环境评价工作的通知》中关于开展营商环境评价的工作要求建设三级联网全覆盖的一体化网上服务体系。通过标准化办事要件和办事指南，规范服务事项，让企业和群众办事更加高效、便捷。明确各环节协同事项，整合数据资源，提高内部业务流转效率，实现“一网通办”。</p><p>有效地助力政府部门开展银企对接服务，通过系统及时展示最新优惠政策，做到信息公开化，为企业提供强支持。最终通过营商环境门户系统建设强化整顿和规范市场经济秩序，为企业发展营造公平竞争、规范有序的市场环境。</p><h3>新闻宣传</h3><ul><li>免申即享、免证可办等业务相关新闻及政策及时发布</li></ul><h3>成果展示</h3><ul><li>住建、金融等线下成果线上展示</li></ul><h3>数据共享</h3><ul><li>内部数据资源共享</li></ul><h3>应用对接</h3><ul><li>跨省通办、全豫通办、信用查询等应用对接</li></ul><h3>方案图解</h3><p><img src="/images/huanjing.png" alt="营商环境门户平台方案图解"></p>', 'REMOTE_DEPLOY', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '含 1 年免费运维与版本升级', 0, 1, 4);
