INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (5, 3, 'bigdata-dev', '大数据二次开发平台', '助推研发效能提升，加速信息化建设进程，推进企业数字化转型', '可视化开发工具与预设组件库，拖拽配置即可快速搭建应用，代码标准化、易于维护升级。', '/images/jiejuefive.jpg', '["/images/jiejuefive.jpg", "/images/dashuju.png"]', '<p>随着数字经济的蓬勃发展，各行各业都在加速数字化转型，对快速响应市场变化、灵活调整业务流程的需求日益迫切。大数据二次开发平台提供了一种高效、灵活的方式，能够帮助企业快速构建和迭代应用，支撑其数字化转型战略。</p><h3>快速开发</h3><ul><li>提供可视化开发工具和预设组件库，缩短开发周期</li></ul><h3>简单易用</h3><ul><li>通过拖拽配置等简单操作即可完成快速搭建，无需深入编码</li></ul><h3>易维护</h3><ul><li>项目代码标准化、易于维护和升级</li></ul><h3>方案图解</h3><p><img src="/images/dashuju.png" alt="大数据二次开发平台方案图解"></p>', 'ONLINE_OPEN', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '订阅期内持续提供运维与版本升级', 0, 1, 5);
