INSERT INTO solution (id, category_id, slug, name, subtitle, summary, main_image, gallery, content, delivery_mode, after_sales, service_period, recommended, status, sort) VALUES (6, 3, 'iot', '物联网开发平台', '助力城市治理方式数智化转型，推动城市智慧化进程', '“云、管、端”开放架构的一零物联网平台，以信息采集为基础、业务中台对外提供服务支撑。', '/images/jiejuesix.jpg', '["/images/jiejuesix.jpg", "/images/wulianwang.png"]', '<p>随着智能终端的普及和互联网的快速发展，物联网产业已由信息网络向全面感知和智能应用两个方向扩展、延伸以及突破，形成“云、管、端”的开放网络架构。</p><p>结合目前人民群众对软件应用系统要求易获取、易操作、高流畅等特点，北京一零科技有限公司根据多年技术积累和业务沉淀，以信息采集工作为基础，通过业务中台对外提供服务支撑，建立一零物联网平台。一零物联网开发平台致力于提升公共安全和政务服务水平，提高民众满意度和信任度，助力城市治理方式数智化转型，推动城市智慧化进程。</p><h3>数据中台</h3><ul><li>数据比对</li><li>数据整合</li><li>数据清洗</li><li>数据分析</li><li>数据碰撞</li></ul><h3>应用场景</h3><ul><li>城市交通</li><li>智慧社区</li><li>智慧教育</li><li>治安管理</li><li>公共卫生</li></ul><h3>物联网感知终端</h3><ul><li>视频监控</li><li>微热点</li><li>射频识别设备</li><li>警用智能终端</li><li>门禁</li><li>云音箱</li><li>无人机</li><li>AI智能执法记录仪</li><li>道闸</li></ul><h3>方案图解</h3><p><img src="/images/wulianwang.png" alt="物联网开发平台方案图解"></p>', 'ONLINE_OPEN', '工作日 9:00–18:00 远程技术支持，2 小时内响应；重大故障 7×24 小时响应', '订阅期内持续提供运维与版本升级', 0, 1, 6);
