INSERT INTO news (title, summary, content, published_at, top, status) VALUES ('一零科技官网全新改版上线', '官网完成改版，解决方案支持在线查看价格与在线购买。', '<p>北京一零科技有限公司官网完成全新改版。新版官网对解决方案进行了全面梳理，各方案的版本、价格与增值服务均在线公示，客户可在线下单并通过微信扫码支付，也可在用户中心随时查看订单与服务进度。</p><p>如需咨询，欢迎致电 136 9928 5133。</p>', NOW(), 1, 1);
